import{_ as a,o as e,c as i,a5 as s}from"./chunks/framework.a5no_H3L.js";const h=JSON.parse('{"title":"RabbitMQ 概览","description":"选 RabbitMQ 不是因为它\\"最好\\"，而是因为在\\"业务消息 + 复杂路由 + 低延迟\\"这个组合需求下，它是最成熟的选择。","frontmatter":{},"headers":[],"relativePath":"rabbitmq/01-basics/chapter-01-overview.md","filePath":"rabbitmq/01-basics/chapter-01-overview.md"}'),r={name:"rabbitmq/01-basics/chapter-01-overview.md"};function l(d,t,c,n,b,o){return e(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="rabbitmq-概览" tabindex="-1" data-src-line="1" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">RabbitMQ 概览 <a class="header-anchor" href="#rabbitmq-概览" aria-label="Permalink to &quot;RabbitMQ 概览&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><p data-src-line="3" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">选 RabbitMQ 不是因为它&quot;最好&quot;，而是因为在&quot;业务消息 + 复杂路由 + 低延迟&quot;这个组合需求下，它是最成熟的选择。</p><p data-src-line="5" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">本文档的版本结论以 <strong>RabbitMQ 4.3 系列</strong>（截至 2026-09，最新补丁 4.3.6）为基准。更早期的版本建议见下方第 9 节。</p></blockquote><h2 id="_1-rabbitmq-是什么" tabindex="-1" data-src-line="7" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">1. RabbitMQ 是什么 <a class="header-anchor" href="#_1-rabbitmq-是什么" aria-label="Permalink to &quot;1. RabbitMQ 是什么&quot;">​</a></h2><p data-src-line="9" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">RabbitMQ 是一个实现了 AMQP 0-9-1 协议的消息代理（Message Broker）。它的核心工作很简单：接收生产者发来的消息，根据路由规则投递给消费者。</p><p data-src-line="11" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">但&quot;简单&quot;不等于&quot;浅&quot;。在一个分布式系统里，&quot;可靠地把消息从 A 搬到 B&quot;这件事，涉及消息持久化、确认机制、死信处理、集群高可用、网络分区恢复等一系列工程问题。RabbitMQ 经过长期生产检验，提供了应对这些问题的成熟机制——但最终的可靠性保证取决于你的配置、故障类型，以及应用层的处理方式（详见<a href="#7-可靠性保障层次">可靠性保障层次</a>）。</p><h2 id="_2-为什么需要消息队列" tabindex="-1" data-src-line="13" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">2. 为什么需要消息队列 <a class="header-anchor" href="#_2-为什么需要消息队列" aria-label="Permalink to &quot;2. 为什么需要消息队列&quot;">​</a></h2><p data-src-line="15" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">直接调用（HTTP/RPC）和消息队列，本质上解决的是不同的问题：</p><p data-src-line="17" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><strong>直接调用</strong>：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>服务A ──HTTP──▶ 服务B</span></span>
<span class="line"><span>           等待响应</span></span>
<span class="line"><span>           ◀──────</span></span></code></pre></div><ul data-src-line="25" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><li data-src-line="25" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">强耦合：B 挂了 A 也挂</li><li data-src-line="26" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">同步阻塞：A 必须等 B 处理完</li><li data-src-line="27" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">无缓冲：突发流量直接打垮 B</li></ul><p data-src-line="29" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><strong>消息队列</strong>：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>服务A ──▶ [Queue] ──▶ 服务B</span></span>
<span class="line"><span>         消息暂存      异步处理</span></span></code></pre></div><ul data-src-line="36" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><li data-src-line="36" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">解耦：A 只管发，不关心谁消费</li><li data-src-line="37" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">异步：A 发完就走，不等 B</li><li data-src-line="38" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">削峰：Queue 充当缓冲区，B 按自己的速率消费</li></ul><p data-src-line="40" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">但这不是说消息队列比直接调用&quot;更好&quot;。它引入了新的复杂性：消息丢失的风险、消费顺序问题、幂等性要求、运维成本。<strong>如果同步调用能满足需求，不要引入消息队列。</strong></p><h2 id="_3-rabbitmq-的核心优势" tabindex="-1" data-src-line="42" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">3. RabbitMQ 的核心优势 <a class="header-anchor" href="#_3-rabbitmq-的核心优势" aria-label="Permalink to &quot;3. RabbitMQ 的核心优势&quot;">​</a></h2><p data-src-line="44" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">RabbitMQ 与 Kafka 的设计重点不同。RabbitMQ 围绕 Exchange、Binding 和 Queue 构建消息路由，适合需要灵活分发业务事件的场景；Kafka 以 Topic、Partition 和消费组为核心，更适合高吞吐、可回放的事件流场景。两者存在能力交集，但不能仅凭单一指标判断优劣。</p><table tabindex="0"><thead data-src-line="46" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><tr data-src-line="46" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><th style="text-align:left;">维度</th><th style="text-align:left;">RabbitMQ</th><th style="text-align:left;">Kafka</th></tr></thead><tbody data-src-line="48" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><tr data-src-line="48" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">路由模型</td><td style="text-align:left;">通过 Direct/Topic/Fanout/Headers Exchange 与 Binding 组合路由规则，可将消息分发到一个或多个队列</td><td style="text-align:left;">以 Topic 和 Partition 组织消息，主要通过生产者选分区、消费组订阅与分区分配组织消息流，不提供 AMQP 式 Exchange 路由模型</td></tr><tr data-src-line="49" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">延迟特征</td><td style="text-align:left;">面向消息分发与消费，延迟受队列类型、消息持久化、确认策略、负载与网络等因素影响</td><td style="text-align:left;">延迟受批处理、生产者配置、副本确认策略、消费方式与负载等因素影响</td></tr><tr data-src-line="50" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">协议支持</td><td style="text-align:left;">原生支持 AMQP 0-9-1；4.0 起 AMQP 1.0 成为核心协议；通过插件支持 MQTT、STOMP，并内置 Stream 协议</td><td style="text-align:left;">使用自有二进制协议，拥有多种语言客户端及连接器生态</td></tr><tr data-src-line="51" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">死信处理</td><td style="text-align:left;">通过 Dead Letter Exchange（DLX）及队列参数构建死信流程</td><td style="text-align:left;">没有与 DLX 完全对应的 Broker 级死信路由，通常通过应用或消费框架设计重试与死信主题</td></tr><tr data-src-line="52" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">延迟消息</td><td style="text-align:left;">通过 TTL + DLX 实现延迟投递，4.4 起 Quorum Queue 原生支持投递延迟</td><td style="text-align:left;">通常通过延迟主题、时间戳调度或外部调度机制实现</td></tr><tr data-src-line="53" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">堆积与回放</td><td style="text-align:left;">队列类型不同，堆积、存储与消费语义也不同；Stream Queue 支持按 offset 回放</td><td style="text-align:left;">以持久化分区日志为核心，可在保留策略范围内按 offset 重新消费</td></tr><tr data-src-line="54" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">扩展与高可用</td><td style="text-align:left;">通过多节点集群与合适的队列类型实现；能力取决于队列类型与分布方式</td><td style="text-align:left;">通过分区分布与副本机制扩展；效果取决于分区数、复制配置与负载</td></tr><tr data-src-line="55" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">运维与选型成本</td><td style="text-align:left;">需理解 Exchange、Binding、队列类型、确认与死信等机制</td><td style="text-align:left;">需理解 Topic、Partition、消费组、保留策略、副本与再均衡等机制</td></tr></tbody></table><p data-src-line="57" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">这张表用于确定评估方向，不代表两种产品在所有场景下的绝对优劣。延迟、吞吐、堆积后性能与运维成本尤其不能脱离负载与部署条件直接比较。需要作出容量或性能决策时，应使用贴近生产环境的消息大小、并发度、持久化与确认策略、复制配置及消费模式进行基准测试。</p><h2 id="_4-rabbitmq-不适合什么" tabindex="-1" data-src-line="59" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">4. RabbitMQ 不适合什么 <a class="header-anchor" href="#_4-rabbitmq-不适合什么" aria-label="Permalink to &quot;4. RabbitMQ 不适合什么&quot;">​</a></h2><table tabindex="0"><thead data-src-line="61" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><tr data-src-line="61" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><th style="text-align:left;">场景</th><th style="text-align:left;">问题</th><th style="text-align:left;">替代方案</th></tr></thead><tbody data-src-line="63" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><tr data-src-line="63" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">百万级 QPS 持续吞吐</td><td style="text-align:left;">单队列/单节点吞吐有上限，需靠横向扩展弥补；经典队列堆积后存在内存换页开销</td><td style="text-align:left;">Kafka / Pulsar（吞吐需通过基准测试按实际负载评估，不应视为固定边界）</td></tr><tr data-src-line="64" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">大量消息堆积</td><td style="text-align:left;">经典队列在长时间堆积、内存压力下会换页到磁盘，吞吐受影响</td><td style="text-align:left;">Kafka（顺序写磁盘，长时间堆积场景吞吐通常更稳定）</td></tr><tr data-src-line="65" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">消息回溯</td><td style="text-align:left;">不支持按 offset 重新消费</td><td style="text-align:left;">Kafka（Stream Queue 3.9+ 提供 offset 回放，详见<a href="./../03-queue/chapter-04-stream-queue.html">队列类型</a>）</td></tr><tr data-src-line="66" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">流处理</td><td style="text-align:left;">无原生流处理引擎</td><td style="text-align:left;">Kafka Streams / Flink</td></tr><tr data-src-line="67" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">日志收集</td><td style="text-align:left;">高吞吐场景不是强项</td><td style="text-align:left;">Kafka</td></tr></tbody></table><p data-src-line="69" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><strong>判断标准</strong>：如果你的需求是&quot;业务消息 + 可靠投递 + 灵活路由 + 低延迟&quot;，RabbitMQ 是首选。如果是&quot;大数据量 + 高吞吐 + 消息回溯&quot;，选 Kafka。吞吐&quot;上限&quot;取决于队列类型、节点数、消息大小与确认策略，应以基准测试结论为准。</p><h2 id="_5-核心概念速览" tabindex="-1" data-src-line="71" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">5. 核心概念速览 <a class="header-anchor" href="#_5-核心概念速览" aria-label="Permalink to &quot;5. 核心概念速览&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Producer ──▶ Exchange ──binding──▶ Queue ──▶ Consumer</span></span>
<span class="line"><span>             (路由)               (存储)      (消费)</span></span></code></pre></div><ul data-src-line="78" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><li data-src-line="78" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><strong>Producer</strong>：消息发送者，不直接发到 Queue，而是发到 Exchange</li><li data-src-line="79" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><strong>Exchange</strong>：路由器，根据 binding 规则把消息分发到一个或多个 Queue</li><li data-src-line="80" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><strong>Queue</strong>：消息的最终存储，消费者从这里取消息</li><li data-src-line="81" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><strong>Binding</strong>：Exchange 与 Queue 之间的绑定关系及其匹配条件。常见依据是 routing key（Direct/Topic/Fanout），Headers Exchange 则依据绑定时声明的消息头匹配条件。</li><li data-src-line="82" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><strong>Consumer</strong>：消息消费者，支持推模式（Push）和拉模式（Pull）</li><li data-src-line="83" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><strong>Channel</strong>：建立在 AMQP Connection（复用一个 TCP 连接）之上的逻辑通信通道，而非另一条连接。单个 Connection 上可开辟多个 Channel，避免为每个生产者/消费者都建立独立 TCP 连接的开销。</li><li data-src-line="84" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><strong>Virtual Host（vhost）</strong>：逻辑隔离单元，类似数据库的 schema</li></ul><h2 id="_6-exchange-类型与路由能力" tabindex="-1" data-src-line="86" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">6. Exchange 类型与路由能力 <a class="header-anchor" href="#_6-exchange-类型与路由能力" aria-label="Permalink to &quot;6. Exchange 类型与路由能力&quot;">​</a></h2><table tabindex="0"><thead data-src-line="88" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><tr data-src-line="88" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><th style="text-align:left;">Exchange 类型</th><th style="text-align:left;">路由规则</th><th style="text-align:left;">典型场景</th></tr></thead><tbody data-src-line="90" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><tr data-src-line="90" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">Direct</td><td style="text-align:left;">routing key 精确匹配</td><td style="text-align:left;">点对点、任务分发</td></tr><tr data-src-line="91" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">Topic</td><td style="text-align:left;">routing key 通配符匹配（<code>*</code> 和 <code>#</code>）</td><td style="text-align:left;">事件订阅、分类路由</td></tr><tr data-src-line="92" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">Fanout</td><td style="text-align:left;">忽略 routing key，广播到所有绑定队列</td><td style="text-align:left;">广播通知、实时推送</td></tr><tr data-src-line="93" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">Headers</td><td style="text-align:left;">根据消息 headers 匹配</td><td style="text-align:left;">复杂条件路由（少用）</td></tr></tbody></table><p data-src-line="95" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">通过 Exchange + Binding 的组合，可以覆盖从点对点到发布/订阅的大多数路由需求；更细的绑定与路由规则见<a href="./../02-exchange/chapter-01-exchange-basics.html">Exchange 基础</a>。</p><h2 id="_7-可靠性保障层次" tabindex="-1" data-src-line="97" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">7. 可靠性保障层次 <a class="header-anchor" href="#_7-可靠性保障层次" aria-label="Permalink to &quot;7. 可靠性保障层次&quot;">​</a></h2><p data-src-line="99" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">RabbitMQ 的可靠性不是单一机制，而是多层叠加：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Producer                    Broker                     Consumer</span></span>
<span class="line"><span>  │                           │                           │</span></span>
<span class="line"><span>  ├─ Publisher Confirm ──▶    ├─ 持久化（Durable Queue）   ├─ Manual ACK</span></span>
<span class="line"><span>  │  (发布端可靠性: Broker    ├─ 持久化（Persistent Msg）  ├─ (消费端可靠性: 处理成功</span></span>
<span class="line"><span>  │   已确认接收并处理)        ├─ Quorum 队列复制           │   后才确认，失败可重投)</span></span>
<span class="line"><span>  ├─ Mandatory Return ──▶     └─ 事务（性能差，少用）       └─ 重试 + DLX</span></span>
<span class="line"><span>  │  (路由失败可感知，与Confirm不同)</span></span></code></pre></div><p data-src-line="111" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">每一层解决不同的问题，三者分属不同故障窗口：</p><ul data-src-line="113" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><li data-src-line="113" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><strong>生产端</strong>：Publisher Confirm 确认 Broker 已接收并处理该发布（持久消息进入持久队列时，确认意味着相应持久化已完成；Quorum 队列则需多数副本接受）。它并非对任意故障下&quot;消息绝不丢失&quot;的无条件承诺；Mandatory + Return 负责感知&quot;消息无法路由到任何队列&quot;——它和 Confirm 是两套独立判断，Confirm 成功不等于消息一定进了目标队列。</li><li data-src-line="114" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><strong>Broker 端</strong>：Durable Queue 保证队列元数据与（持久化）消息在重启后存活；持久化消息属性决定单条消息是否落盘；Quorum 队列通过 Raft 复制提供节点故障容错。持久化配置本身不构成&quot;消息已安全落盘&quot;的保证，仍需 Confirm 配合。</li><li data-src-line="115" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><strong>消费端</strong>：Manual ACK 在业务处理成功后才确认，处理失败或崩溃时消息可重新投递。Manual ACK 是消费端的投递确认，并不等同于业务事务的提交边界——若先 ACK 再提交业务、或提交业务后 ACK 前崩溃，都可能导致重复或丢失，因此仍需配合幂等处理。</li></ul><p data-src-line="117" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">生产环境通常以 <strong>Durable Queue + Persistent Message + Publisher Confirm + Manual ACK</strong> 作为可靠性基线。但这只是基础配置，不等于端到端恰好一次：生产者仍需处理不可路由消息，消费者仍需处理重复投递并做幂等。底层机制与协议细节见<a href="./../04-producer/chapter-02-publisher-confirm.html">发布确认</a>、<a href="./../05-consumer/chapter-02-ack-mechanism.html">ACK 机制</a>与<a href="./../03-queue/chapter-03-quorum-queue.html">仲裁队列</a>。</p><h2 id="_8-典型使用场景" tabindex="-1" data-src-line="119" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">8. 典型使用场景 <a class="header-anchor" href="#_8-典型使用场景" aria-label="Permalink to &quot;8. 典型使用场景&quot;">​</a></h2><h3 id="_8-1-电商订单流程" tabindex="-1" data-src-line="121" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">8.1 电商订单流程 <a class="header-anchor" href="#_8-1-电商订单流程" aria-label="Permalink to &quot;8.1 电商订单流程&quot;">​</a></h3><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                     ┌──▶ inventory.queue    ──▶ 库存服务（扣库存）</span></span>
<span class="line"><span>下单 ──▶ order.exchange ├──▶ notification.queue ──▶ 通知服务（发短信）</span></span>
<span class="line"><span>                     └──▶ points.queue       ──▶ 积分服务（加积分）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>（Fanout 或 Topic Exchange，三个队列各自绑定到 Exchange）</span></span></code></pre></div><p data-src-line="131" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">一条订单事件进入三个独立队列，每个服务消费自己队列里的消息。需要强调的是：RabbitMQ 中多个消费者订阅<strong>同一个队列</strong>时是竞争消费（一条消息只投递给其中一个消费者），并不会自动广播给所有消费者。要让库存、通知、积分三个服务都处理同一事件，必须分别绑定三个队列到 Exchange，由 Exchange 的路由规则决定哪些队列收到消息。Exchange 与绑定规则详见<a href="./../02-exchange/chapter-01-exchange-basics.html">Exchange 基础</a>。</p><h3 id="_8-2-延迟任务" tabindex="-1" data-src-line="133" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">8.2 延迟任务 <a class="header-anchor" href="#_8-2-延迟任务" aria-label="Permalink to &quot;8.2 延迟任务&quot;">​</a></h3><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>订单创建 ──▶ delay.order.timeout.queue（TTL 30 分钟）──▶ order.timeout.queue ──▶ 检查支付状态</span></span></code></pre></div><p data-src-line="139" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">消息先进入带 TTL 的延迟队列，到期后经 DLX 路由到处理队列。RabbitMQ 4.3 下延迟消息插件（rabbitmq_delayed_message_exchange）已停止维护且依赖的 Mnesia 已移除，实现细节见<a href="./../05-consumer/chapter-04-message-ttl.html">消息 TTL</a>。</p><h3 id="_8-3-rpc-调用" tabindex="-1" data-src-line="141" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">8.3 RPC 调用 <a class="header-anchor" href="#_8-3-rpc-调用" aria-label="Permalink to &quot;8.3 RPC 调用&quot;">​</a></h3><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Client ──▶ request.queue ──▶ Server</span></span>
<span class="line"><span>       ◀── reply.queue ◀──</span></span></code></pre></div><p data-src-line="148" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">RabbitMQ 可用于构建 RPC 消息模式（借助 reply-to 与关联 ID），适用于需要异步调用但又要返回结果的场景。这不等同于 Broker 提供了完整的原生 RPC 调用语义——请求/响应配对、超时与错误处理仍需应用层实现。</p><h2 id="_9-版本选择建议" tabindex="-1" data-src-line="150" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">9. 版本选择建议 <a class="header-anchor" href="#_9-版本选择建议" aria-label="Permalink to &quot;9. 版本选择建议&quot;">​</a></h2><p data-src-line="152" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">本文以 <strong>RabbitMQ 4.3 系列</strong>（截至 2026-09，最新补丁 4.3.6）为当前基准。版本选择应先看业务对复制、高可用、延迟与消息回溯的要求，再决定队列类型与版本，而非简单按&quot;最新&quot;排序。</p><table tabindex="0"><thead data-src-line="154" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><tr data-src-line="154" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><th style="text-align:left;">版本系列</th><th style="text-align:left;">关键特征</th><th style="text-align:left;">建议</th></tr></thead><tbody data-src-line="156" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><tr data-src-line="156" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">4.3.x</td><td style="text-align:left;">当前主线；Khepri 成为唯一元数据存储，Mnesia 已移除，统一 Raft 故障模型</td><td style="text-align:left;">新项目首选</td></tr><tr data-src-line="157" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">4.2.x</td><td style="text-align:left;">Khepri 成为新集群默认元数据存储；社区支持已结束（2026-07），仅商业支持</td><td style="text-align:left;">生产可用，规划升级到 4.3</td></tr><tr data-src-line="158" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">4.1.x / 4.0.x</td><td style="text-align:left;">4.0 起移除经典镜像队列；4.1 起 Khepri 可选</td><td style="text-align:left;">仅商业支持，建议升级</td></tr><tr data-src-line="159" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">3.13.x 及更早</td><td style="text-align:left;">经典镜像队列仍可用（3.13 实验性 Khepri）</td><td style="text-align:left;">不推荐新项目，逐步迁移</td></tr></tbody></table><p data-src-line="161" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><strong>关键变化（跨大版本升级务必注意）</strong>：RabbitMQ 4.0 起<strong>彻底移除了经典镜像队列（Classic Mirrored Queue）</strong>，复制型队列只保留 Quorum Queue 与 Stream Queue。从 3.x 升级到 4.x 是破坏性变更，需经 3.13 → 4.2 → 4.3 逐级升级并开启相应 feature flag（升级前用 <code>rabbitmqctl list_feature_flags</code> 确认必需 flag 已启用）；旧版基于镜像队列的运维经验不能直接套用到 4.x。<strong>例外</strong>：若 3.13 集群已开启 Khepri 元数据存储，则无法按常规方式原地升级到 4.x，需规划蓝绿迁移等替代方案。新项目应直接使用 Quorum Queue，不要使用镜像队列。详细的队列类型与迁移见<a href="./../03-queue/chapter-03-quorum-queue.html">仲裁队列</a>与<a href="./../07-clustering/chapter-01-cluster-basics.html">集群基础</a>。</p>`,47)])])}const m=a(r,[["render",l]]);export{h as __pageData,m as default};
